"""Add an explicit, source-backed city governance edge when endpoints are certain."""

from __future__ import annotations

import re
from copy import deepcopy
from dataclasses import replace
from typing import Any

from .extraction_profile import register_extraction_profile
from .worldbuilding_gazetteer_role_citations import _affirmed_role_occurrence
from .worldbuilding_gazetteer_scenario_scope import (
    GAZETTEER_PREPARED_SCENARIO_PROFILE,
    _heading,
    _ordered_rows,
    compile_gazetteer_scenario_scope,
)


PROFILE_VERSION = "1.9"
PROFILE = f"worldbuilding_gazetteer_v1@{PROFILE_VERSION}"
_CITY_GOVERNANCE = re.compile(
    r"\bcity[\s-]+state\s+(?:is\s+)?governed\s+by\s+(?:a|the)\s+council\b",
    re.IGNORECASE,
)
_CITY_TITLE = re.compile(r"^(?:the\s+)?city\s+of\s+(.+)$", re.IGNORECASE)


def _normalized_label(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").casefold()).strip()


def _physical_source_lines(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Expand indexed spans to physical lines without losing their source IDs."""
    physical = []
    for row in _ordered_rows(rows):
        start = row["line_start"]
        end = row["line_end"]
        lines = row["text"].splitlines()
        if len(lines) != end - start + 1:
            raise ValueError("source span text does not match its physical line range")
        for offset, text in enumerate(lines):
            physical.append({
                **row,
                "line_start": start + offset,
                "line_end": start + offset,
                "text": text,
            })
    return physical


def _document_city_title(
    rows: list[dict[str, Any]],
) -> tuple[str, dict[str, Any]] | None:
    lines = _physical_source_lines(rows)
    frontmatter_titles = []
    frontmatter_open = bool(
        lines and lines[0].get("line_start") == 1 and lines[0]["text"].strip() == "---"
    )
    if frontmatter_open:
        frontmatter_closed = False
        for row in lines[1:]:
            text = row["text"].strip()
            if text == "---":
                frontmatter_closed = True
                break
            match = re.fullmatch(r"title\s*:\s*(.*?)\s*", text, re.IGNORECASE)
            if match:
                value = match.group(1).strip()
                if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
                    value = value[1:-1]
                frontmatter_titles.append((value, row))
        if not frontmatter_closed:
            return None
        if len(frontmatter_titles) == 1:
            title, row = frontmatter_titles[0]
            title_match = _CITY_TITLE.fullmatch(title.strip())
            return (title_match.group(1).strip(), row) if title_match else None
        if len(frontmatter_titles) > 1:
            return None

    titles = []
    for row in lines:
        heading = _heading(row["text"])
        if heading is None or heading[0] != 1:
            continue
        match = _CITY_TITLE.fullmatch(heading[1].rstrip(":").strip())
        if match:
            titles.append((match.group(1).strip(), row))
    return titles[0] if len(titles) == 1 else None


def _affirmed_city_governance(text: str) -> bool:
    # Preserve shared and introductory qualifiers using the reviewed claim rules.
    return any(
        _affirmed_role_occurrence(text, match.group(0))
        for match in _CITY_GOVERNANCE.finditer(text)
    )


def _governance_subject_matches(text: str, city_name: str) -> bool:
    """Bind narrow source templates to this city; defer ambiguous prose.

    The section scopes article-led descriptions, not another named city. Check
    affirmation and subject binding on the same governance occurrence.
    """
    city = _normalized_label(city_name)
    subjects = {city, f"city of {city}", f"the city of {city}", "it", "the city"}
    for match in _CITY_GOVERNANCE.finditer(text):
        if not _affirmed_role_occurrence(text, match.group(0)):
            continue
        prefix = re.split(r"[.!?;]", text[:match.start()])[-1].strip()
        # Keep the original subject when correcting a prior negative assertion.
        prefix = re.sub(r"\s+was not\s+[^,;.!?]+\s+but is\s+", " is ", prefix,
                        flags=re.IGNORECASE)
        explicit = re.fullmatch(r"(.+?)\s+is\s+(.+)", prefix, re.IGNORECASE)
        if explicit:
            subject, description = explicit.groups()
            if _normalized_label(subject) not in subjects:
                continue
        else:
            description = prefix
        if re.fullmatch(
            r"(?:a|an)(?:\s+(?:democratic|autonomous|independent|sovereign))*",
            description.strip(), re.IGNORECASE,
        ):
            return True
    return False


def _governance_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    lines = _physical_source_lines(rows)
    in_governance = False
    governance_level: int | None = None
    matches = []
    for row in lines:
        heading = _heading(row["text"])
        if heading is not None:
            level, title = heading
            normalized_title = title.rstrip(":").strip().casefold()
            if in_governance and governance_level is not None and level <= governance_level:
                in_governance = False
                governance_level = None
            if normalized_title == "governance" and level >= 2:
                in_governance = True
                governance_level = level
            continue
        if in_governance and _affirmed_city_governance(row["text"]):
            matches.append(row)
    return matches


def _matching_city_nodes(nodes: list[dict[str, Any]], city_name: str) -> list[dict[str, Any]]:
    target = _normalized_label(city_name)
    return [
        node for node in nodes
        if node.get("node_type") == "location"
        and _normalized_label(node.get("label")) in {
            target,
            f"city of {target}",
            f"the city of {target}",
        }
    ]


def _matching_council_nodes(
    nodes: list[dict[str, Any]], city_name: str,
) -> list[dict[str, Any]]:
    city = _normalized_label(city_name)
    accepted_labels = {
        f"{city} city council",
        f"city council of {city}",
        f"{city} council",
        f"council of {city}",
    }
    return [
        node for node in nodes
        if node.get("node_type") in {"organization", "faction"}
        and _normalized_label(node.get("label")) in accepted_labels
    ]


def _openable_source_evidence(
    node: dict[str, Any], *, span_ref: str, source_text: str,
) -> dict[str, Any] | None:
    refs = node.get("evidence_refs")
    if not isinstance(refs, list):
        return None
    for ref in refs:
        if not isinstance(ref, dict) or ref.get("source_span_ref_id") != span_ref:
            continue
        quotes = ref.get("anchor_quotes")
        if (
            isinstance(quotes, list)
            and source_text in quotes
            and ref.get("source_artifact_id")
            and ref.get("source_ref_id")
            and ref.get("source_anchor_id")
            and ref.get("evidence_role") == "source_evidence"
            and ref.get("can_open_source") is True
        ):
            return ref
    return None


def _title_context_evidence(
    title_row: dict[str, Any], *, source_template: dict[str, Any],
) -> dict[str, Any] | None:
    """Materialize a source anchor for the title line from the registered source."""
    from .category_candidate_graph_extractor import materialize_promote_evidence_ref

    evidence = materialize_promote_evidence_ref(
        {
            "source_span_ref_id": title_row["source_span_ref_id"],
            "anchor_quotes": [title_row["text"]],
        },
        source_artifact_id=str(source_template.get("source_artifact_id") or ""),
        source_ref_id=str(source_template.get("source_ref_id") or ""),
    )
    if (
        evidence is None
        or evidence.get("can_open_source") is not True
        or not evidence.get("source_anchor_id")
    ):
        return None
    return evidence


def _append_evidence_once(node: dict[str, Any], evidence: dict[str, Any]) -> bool:
    refs = node.get("evidence_refs")
    if not isinstance(refs, list):
        return False
    span_ref = evidence.get("source_span_ref_id")
    if any(
        isinstance(ref, dict) and ref.get("source_span_ref_id") == span_ref
        for ref in refs
    ):
        return False
    refs.append(deepcopy(evidence))
    return True


def _apply_governance_relation(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Add only the uniquely name-bound relation explicitly stated by the source.

    Both endpoint candidates must already exist and carry the same openable exact
    Governance passage. This postprocessor never invents nodes or repairs an
    ambiguous or reversed model edge.
    """
    result = deepcopy(graph)
    nodes = result.get("nodes")
    edges = result.get("edges")
    if not isinstance(nodes, list) or not isinstance(edges, list):
        raise ValueError("candidate graph nodes and edges must be lists")
    if any(not isinstance(node, dict) for node in nodes):
        raise ValueError("candidate graph nodes must be objects")
    if any(not isinstance(edge, dict) for edge in edges):
        raise ValueError("candidate graph edges must be objects")

    statements = _governance_rows(_ordered_rows(rows))
    if not statements:
        return result, {"profile": PROFILE, "status": "not_applicable"}
    if len(statements) != 1:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "multiple_governance_statements",
        }
    city_title = _document_city_title(rows)
    if city_title is None:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "city_title_unresolved",
        }
    city_name, title_row = city_title
    if not _governance_subject_matches(statements[0]["text"], city_name):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "governance_subject_not_bound",
        }
    city_nodes = _matching_city_nodes(nodes, city_name)
    council_nodes = _matching_council_nodes(nodes, city_name)
    if len(city_nodes) != 1 or len(council_nodes) != 1:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "governance_endpoints_not_unique",
            "city_node_count": len(city_nodes),
            "council_node_count": len(council_nodes),
        }

    statement = statements[0]
    span_ref = statement["source_span_ref_id"]
    city = city_nodes[0]
    council = council_nodes[0]
    city_ref = _openable_source_evidence(
        city, span_ref=span_ref, source_text=statement["text"]
    )
    council_ref = _openable_source_evidence(
        council, span_ref=span_ref, source_text=statement["text"]
    )
    if city_ref is None or council_ref is None:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "endpoint_missing_openable_governance_evidence",
            "source_span_ref_id": span_ref,
        }
    if (
        city_ref.get("source_artifact_id") != council_ref.get("source_artifact_id")
        or city_ref.get("source_ref_id") != council_ref.get("source_ref_id")
    ):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "endpoint_source_binding_mismatch",
            "source_span_ref_id": span_ref,
        }
    title_ref = _title_context_evidence(title_row, source_template=city_ref)
    if title_ref is None:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "city_title_has_no_openable_source_anchor",
            "source_span_ref_id": span_ref,
        }

    council_id = str(council.get("node_id") or "").strip()
    city_id = str(city.get("node_id") or "").strip()
    if not council_id or not city_id or council_id == city_id:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "invalid_governance_endpoints",
            "source_span_ref_id": span_ref,
        }
    if (
        not isinstance(city.get("semantic_state"), dict)
        or city.get("semantic_state") != council.get("semantic_state")
    ):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "governance_endpoint_state_mismatch",
            "source_span_ref_id": span_ref,
        }

    exact = [
        edge for edge in edges
        if edge.get("relationship_type") == "governs"
        and edge.get("from_node_id") == council_id
        and edge.get("to_node_id") == city_id
    ]
    reversed_edges = [
        edge for edge in edges
        if edge.get("relationship_type") == "governs"
        and edge.get("from_node_id") == city_id
        and edge.get("to_node_id") == council_id
    ]
    if reversed_edges or len(exact) > 1:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "conflicting_or_duplicate_governance_edge",
            "source_span_ref_id": span_ref,
        }
    if exact and not isinstance(exact[0].get("evidence_refs"), list):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "existing_governance_edge_has_invalid_evidence",
            "source_span_ref_id": span_ref,
        }

    edge_id = f"edge:{council_id}:governs:{city_id}"
    id_collision = next(
        (edge for edge in edges if edge.get("edge_id") == edge_id and edge not in exact),
        None,
    )
    if id_collision is not None:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "governance_edge_id_collision",
            "source_span_ref_id": span_ref,
        }

    attached_city_title = _append_evidence_once(city, title_ref)
    attached_council_title = _append_evidence_once(council, title_ref)

    if exact:
        edge = exact[0]
        attached_governance_evidence = _append_evidence_once(edge, city_ref)
        attached_title_evidence = _append_evidence_once(edge, title_ref)
        status = (
            "evidence_attached"
            if attached_city_title or attached_council_title
            or attached_governance_evidence or attached_title_evidence
            else "already_present"
        )
        edge_id = str(edge.get("edge_id") or edge_id)
    else:
        semantic_state = council.get("semantic_state")
        if not isinstance(semantic_state, dict):
            return result, {
                "profile": PROFILE,
                "status": "skipped",
                "reason": "council_semantic_state_missing",
                "source_span_ref_id": span_ref,
            }
        edges.append({
            "edge_id": edge_id,
            "from_node_id": council_id,
            "to_node_id": city_id,
            "label": "governs",
            "relationship_type": "governs",
            "semantic_state": deepcopy(semantic_state),
            "evidence_refs": [deepcopy(city_ref), deepcopy(title_ref)],
            "proposed_action": "create",
            "confidence": "high",
            "warnings": [],
        })
        status = "added"

    return result, {
        "profile": PROFILE,
        "status": status,
        "edge_id": edge_id,
        "from_node_id": council_id,
        "to_node_id": city_id,
        "source_span_ref_id": span_ref,
        "title_span_ref_id": title_ref["source_span_ref_id"],
    }


def compile_gazetteer_governance_relations(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    result, diagnostics = compile_gazetteer_scenario_scope(graph, rows)
    result, governance_diagnostics = _apply_governance_relation(result, rows)
    diagnostics["source_grounded_governance"] = governance_diagnostics
    return result, diagnostics


GAZETTEER_GOVERNANCE_PROFILE = register_extraction_profile(replace(
    GAZETTEER_PREPARED_SCENARIO_PROFILE,
    profile_version=PROFILE_VERSION,
    source_section_retainer=compile_gazetteer_governance_relations,
))

"""Deterministically restore exact role-line citations for Gazetteer characters."""

from __future__ import annotations

from dataclasses import replace
import re
from typing import Any

from .extraction_profile import register_extraction_profile
from .worldbuilding_gazetteer_profile import (
    GAZETTEER_LIVESTOCK_HYGIENE_PROFILE,
    compile_gazetteer_livestock_hygiene,
)

PROFILE_ID = "worldbuilding_gazetteer_v1"
PROFILE_VERSION = "1.7"
PROFILE = f"{PROFILE_ID}@{PROFILE_VERSION}"
_PRIOR_PROFILE = "worldbuilding_gazetteer_v1@1.6"
_PROFILE_WARNING = f"source_support_policy:{PROFILE}"
_UNCERTAIN_ROLE_PREFIX = re.compile(
    r"\b(?:perhaps|possibly|potentially|allegedly|purportedly)\b", re.IGNORECASE,
)
_MODAL_ROLE_PREFIX = re.compile(
    r"\b(?:may|might|could|would|should|will)\s+(?!is\b|was\b|has\b)"
    r"(?:[a-z'-]+\s+)*(?:be|become|serve|act|hold|remain|take|assume)\b",
    re.IGNORECASE,
)
_CONDITIONAL_ROLE_CLAUSE = re.compile(
    r"\b(?:if|unless|provided\s+that|subject\s+to)\b", re.IGNORECASE,
)
_NEGATED_ROLE_PREFIX = re.compile(
    r"\b(?:not(?!\s+only\b)|never|no\s+longer|formerly|former|"
    r"isn['’]t|wasn['’]t)\b", re.IGNORECASE,
)
_INDEPENDENT_ROLE_CLAUSE = re.compile(
    r"\b(?:and|but|yet|while|whereas)\s+"
    r"(?:[a-z][\w'-]*\s+)?(?=(?:is|are|serves|acts|holds|works)\b)",
    re.IGNORECASE,
)
_FOLLOWING_PREDICATE = re.compile(
    r"\b(?:and|but|yet|while|whereas)\s+(?:[a-z][\w'-]*\s+)?"
    r"(?=(?:is|are|serves|acts|holds|works)\b|"
    r"(?:may|might|will|would|could|can|should)\s+[a-z])", re.IGNORECASE,
)


def _normalized(value: Any) -> str:
    text = str(value or "").replace("**", "").replace("__", "")
    return re.sub(r"\s+", " ", text).strip().removesuffix(".")


def _role_value(row: dict[str, Any]) -> str | None:
    raw = str(row.get("text") or "").strip()
    for marker in ("**", "__", "*", "_"):
        if raw.startswith(marker):
            closing = raw.find(marker, len(marker))
            if closing > len(marker):
                raw = raw[len(marker):closing] + raw[closing + len(marker):]
            break
    label, separator, value = raw.partition(":")
    if not separator or label.strip().casefold() != "role":
        return None
    role = _normalized(value.strip().strip("*_` "))
    return role or None


def _affirmed_role_occurrence(description: str, role: str) -> bool:
    text = _normalized(description)
    pattern = re.compile(rf"(?<!\w){re.escape(role)}(?!\w)", re.IGNORECASE)
    for match in pattern.finditer(text):
        # Qualifiers belong to the containing sentence, not an arbitrary window.
        start = max(text.rfind(mark, 0, match.start()) for mark in ".!?;") + 1
        ends = [text.find(mark, match.end()) for mark in ".!?;"]
        end = min((index for index in ends if index >= 0), default=len(text))
        before = text[start:match.start()]
        after = text[match.end():end]
        # A separate coordinated clause may qualify a future action rather than
        # the present role. A modal must introduce a predicate, so names such as
        # May and Will do not count as uncertainty on their own.
        prefix = _INDEPENDENT_ROLE_CLAUSE.split(before)[-1]
        suffix = _FOLLOWING_PREDICATE.split(after, maxsplit=1)[0]
        if (
            _UNCERTAIN_ROLE_PREFIX.search(before)
            or _MODAL_ROLE_PREFIX.search(prefix)
            or _CONDITIONAL_ROLE_CLAUSE.search(before + " " + suffix)
        ):
            continue
        if _NEGATED_ROLE_PREFIX.search(prefix):
            continue
        if re.match(
            r"\s*(?:but\s+)?(?:not|never|no longer|formerly)\b",
            after,
            re.IGNORECASE,
        ):
            continue
        return True
    return False


def compile_gazetteer_role_citations(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Apply v1.6 hygiene, then cite only an already-present unique role claim."""
    result, diagnostics = compile_gazetteer_livestock_hygiene(graph, rows)
    hygiene = diagnostics.get("livestock_semantic_hygiene")
    if isinstance(hygiene, dict):
        hygiene["profile"] = PROFILE
    for item in result.get("deferred_items", []):
        if not isinstance(item, dict) or not isinstance(item.get("warnings"), list):
            continue
        item["warnings"] = [
            _PROFILE_WARNING if warning == f"source_support_policy:{_PRIOR_PROFILE}" else warning
            for warning in item["warnings"]
        ]

    span_counts: dict[str, int] = {}
    for row in rows:
        span_ref = row.get("source_span_ref_id")
        if isinstance(span_ref, str) and span_ref:
            span_counts[span_ref] = span_counts.get(span_ref, 0) + 1

    records: list[dict[str, str]] = []
    for row in rows:
        role = _role_value(row)
        if role is None:
            continue
        span_ref = row.get("source_span_ref_id")
        text = row.get("text")
        reason: str | None = None
        target: dict[str, Any] | None = None
        if not isinstance(span_ref, str) or not span_ref or not isinstance(text, str) or not text:
            reason = "invalid_source_row"
        elif span_counts.get(span_ref) != 1:
            reason = "ambiguous_source_span"
        else:
            matches = [
                node for node in result.get("nodes", [])
                if isinstance(node, dict)
                and node.get("node_type") == "character"
                and isinstance(node.get("description"), str)
                and _affirmed_role_occurrence(node["description"], role)
            ]
            if len(matches) != 1:
                reason = "ambiguous_character_match" if len(matches) > 1 else "no_matching_character_claim"
            else:
                target = matches[0]
                refs = target.get("evidence_refs")
                if refs is not None and not isinstance(refs, list):
                    reason = "invalid_character_evidence_refs"
                elif any(
                    isinstance(ref, dict) and ref.get("source_span_ref_id") == span_ref
                    for ref in refs or []
                ):
                    reason = "already_cited"

        if reason is not None:
            records.append({"source_span_ref_id": str(span_ref or ""), "decision": reason})
            continue
        assert target is not None
        target.setdefault("evidence_refs", []).append({
            "source_span_ref_id": span_ref,
            "anchor_quotes": [text],
        })
        records.append({
            "source_span_ref_id": span_ref,
            "candidate_node_id": str(target.get("node_id") or ""),
            "decision": "citation_added",
        })

    diagnostics["role_line_citations"] = {"profile": PROFILE, "records": records}
    return result, diagnostics


GAZETTEER_ROLE_CITATION_PROFILE = register_extraction_profile(replace(
    GAZETTEER_LIVESTOCK_HYGIENE_PROFILE,
    profile_version=PROFILE_VERSION,
    source_section_retainer=compile_gazetteer_role_citations,
))

"""Keep explicitly prepared Mirathorn scenes out of durable setting facts."""

from __future__ import annotations

from copy import deepcopy
from dataclasses import replace
from typing import Any

from .extraction_profile import register_extraction_profile
from .worldbuilding_gazetteer_role_citations import (
    GAZETTEER_ROLE_CITATION_PROFILE,
    compile_gazetteer_role_citations,
)
from .worldbuilding_source_sections import SourceSectionRetentionError


PROFILE_ID = "worldbuilding_gazetteer_v1"
PROFILE_VERSION = "1.8"
PROFILE = f"{PROFILE_ID}@{PROFILE_VERSION}"
_PROFILE_WARNING = f"source_support_policy:{PROFILE}"


def _heading(text: str) -> tuple[int, str] | None:
    stripped = text.strip()
    level = 0
    for char in stripped:
        if char != "#":
            break
        level += 1
    if not level or level > 6 or len(stripped) <= level or stripped[level] != " ":
        return None
    return level, stripped[level + 1:].strip().rstrip("#").strip()


def _ordered_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    previous_end = 0
    refs: set[str] = set()
    for row in rows:
        if not isinstance(row, dict):
            raise SourceSectionRetentionError("invalid source span row")
        start = row.get("line_start")
        end = row.get("line_end")
        span_ref = row.get("source_span_ref_id")
        text = row.get("text")
        if (
            isinstance(start, bool) or not isinstance(start, int)
            or isinstance(end, bool) or not isinstance(end, int)
            or start <= previous_end or end < start
            or not isinstance(span_ref, str) or not span_ref or span_ref in refs
            or not isinstance(text, str)
        ):
            raise SourceSectionRetentionError("invalid source span ordering or identity")
        previous_end = end
        refs.add(span_ref)
    return rows


def _physical_source_lines(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Expand grouped source spans while retaining their original identities."""
    physical = []
    for row in _ordered_rows(rows):
        start = row["line_start"]
        end = row["line_end"]
        lines = row["text"].splitlines()
        if len(lines) != end - start + 1:
            raise SourceSectionRetentionError(
                "source span text does not match its physical line range"
            )
        for offset, text in enumerate(lines):
            physical.append({
                **row,
                "line_start": start + offset,
                "line_end": start + offset,
                "text": text,
            })
    return physical


def _section_refs(
    rows: list[dict[str, Any]], *, title: str, heading_level: int,
    stop_levels: set[int], optional: bool = False,
) -> dict[str, Any] | None:
    physical_rows = _physical_source_lines(rows)
    matches = [
        index for index, row in enumerate(physical_rows)
        if (_heading(row["text"]) == (heading_level, title))
    ]
    if not matches and optional:
        return None
    if len(matches) != 1:
        raise SourceSectionRetentionError(
            f"expected one {title!r} source heading; found {len(matches)}"
        )
    start_index = matches[0]
    start_line = physical_rows[start_index]["line_start"]
    next_heading = next((
        row for row in physical_rows[start_index + 1:]
        if (parsed := _heading(row["text"])) is not None
        and parsed[0] in stop_levels
    ), None)
    end_line = next_heading["line_start"] - 1 if next_heading else rows[-1]["line_end"]
    refs = []
    for row in _ordered_rows(rows):
        overlaps = row["line_start"] <= end_line and row["line_end"] >= start_line
        if not overlaps:
            continue
        if row["line_start"] < start_line or row["line_end"] > end_line:
            raise SourceSectionRetentionError(
                f"source span crosses the boundary of {title!r}"
            )
        refs.append(row["source_span_ref_id"])
    return {
        "heading": title,
        "start_line": start_line,
        "end_line": end_line,
        "source_span_ref_ids": refs,
    }


def prepared_scenario_sections(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Find bounded prepared-scene sections without swallowing intervening lore."""
    rows = _ordered_rows(rows)
    if not rows:
        return []
    sections = []
    plot_hooks = _section_refs(
        rows, title="Plot Hooks and Encounters", heading_level=4,
        stop_levels={1, 2}, optional=True,
    )
    if plot_hooks is not None:
        sections.append(plot_hooks)
    approach = _section_refs(
        rows, title="Approach to Mirathorn", heading_level=2,
        stop_levels={1}, optional=True,
    )
    if approach is not None:
        sections.append(approach)
    sections.sort(key=lambda item: item["start_line"])
    previous_end = 0
    for section in sections:
        if section["start_line"] <= previous_end:
            raise SourceSectionRetentionError("prepared-scenario source sections overlap")
        previous_end = section["end_line"]
    return sections


def _span_refs(item: dict[str, Any]) -> list[str | None]:
    evidence_refs = item.get("evidence_refs")
    if not isinstance(evidence_refs, list):
        return []
    return [
        ref.get("source_span_ref_id") if isinstance(ref, dict) else None
        for ref in evidence_refs
    ]


def _with_profile_warning(item: dict[str, Any]) -> None:
    warnings = item.get("warnings")
    if not isinstance(warnings, list):
        warnings = []
        item["warnings"] = warnings
    if _PROFILE_WARNING not in warnings:
        warnings.append(_PROFILE_WARNING)


def _defer(
    result: dict[str, Any], proposals: dict[str, dict[str, Any]], *,
    kind: str, item: dict[str, Any], reason: str, refs: list[str],
) -> None:
    item_id = f"deferred:prepared-scenario:{kind}:{item.get(kind + '_id')}"
    if item_id in proposals or any(
        existing.get("item_id") == item_id
        for existing in result.get("deferred_items", [])
        if isinstance(existing, dict)
    ):
        raise SourceSectionRetentionError("prepared-scenario disposition identity collision")
    proposal = deepcopy(item)
    _with_profile_warning(proposal)
    result.setdefault("deferred_items", []).append({
        "item_id": item_id,
        "label": item.get("label") or item.get(kind + "_id") or "",
        "reason": reason,
        "evidence_refs": [
            deepcopy(ref) for ref in item.get("evidence_refs", [])
            if isinstance(ref, dict)
            and ref.get("source_span_ref_id") in refs
        ],
        "warnings": [_PROFILE_WARNING],
        "suggested_next_step": (
            "Review this proposal as prepared-scene material; do not promote it "
            "as enduring World knowledge without separate source support."
        ),
    })
    proposals[item_id] = {"item_id": item_id, "kind": kind, "proposal": proposal}


def retain_durable_gazetteer_scope(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Defer scene-only proposals and clear contaminated prose from mixed nodes.

    Source passages remain in the immutable source index. A mixed node can remain
    only when a clean, source-backed edge independently establishes its identity;
    in that case its unsupported description and aliases are removed.
    """
    sections = prepared_scenario_sections(rows)
    section_by_ref = {
        span_ref: section["heading"]
        for section in sections
        for span_ref in section["source_span_ref_ids"]
    }
    all_source_refs = {row["source_span_ref_id"] for row in rows}
    result = deepcopy(graph)
    proposals: dict[str, dict[str, Any]] = {}
    if not sections:
        return result, {
            "profile": PROFILE,
            "status": "no_recognized_prepared_scenario_sections",
            "sections": [],
            "deferred_proposals": {},
            "deferred_node_ids": [],
            "deferred_edge_ids": [],
            "sanitized_node_ids": [],
        }

    nodes = result.get("nodes", [])
    edges = result.get("edges", [])
    if not isinstance(nodes, list) or not isinstance(edges, list):
        raise SourceSectionRetentionError("candidate graph nodes and edges must be lists")
    node_by_id = {
        node.get("node_id"): node for node in nodes if isinstance(node, dict)
    }
    if len(node_by_id) != len(nodes) or None in node_by_id:
        raise SourceSectionRetentionError("candidate graph node identities are invalid")

    scene_edge_ids: set[str] = set()
    durable_edge_ids: set[str] = set()
    for edge in edges:
        if not isinstance(edge, dict) or not edge.get("edge_id"):
            raise SourceSectionRetentionError("candidate graph edge identities are invalid")
        refs = _span_refs(edge)
        if any(ref in section_by_ref for ref in refs):
            scene_edge_ids.add(edge["edge_id"])
        elif refs and all(ref in all_source_refs for ref in refs):
            durable_edge_ids.add(edge["edge_id"])

    scene_node_ids: set[str] = set()
    affected_node_ids: set[str] = set()
    for node in nodes:
        refs = _span_refs(node)
        scene_refs = [ref for ref in refs if ref in section_by_ref]
        if not scene_refs:
            continue
        affected_node_ids.add(node["node_id"])
        if refs and all(ref in section_by_ref for ref in refs):
            scene_node_ids.add(node["node_id"])

    durable_incident_edges: dict[str, list[dict[str, Any]]] = {}
    for edge in edges:
        if edge.get("edge_id") not in durable_edge_ids:
            continue
        source_id = edge.get("from_node_id")
        target_id = edge.get("to_node_id")
        if source_id not in node_by_id or target_id not in node_by_id:
            continue
        if source_id in scene_node_ids or target_id in scene_node_ids:
            continue
        durable_incident_edges.setdefault(source_id, []).append(edge)
        durable_incident_edges.setdefault(target_id, []).append(edge)

    kept_nodes: list[dict[str, Any]] = []
    dropped_node_ids: set[str] = set()
    sanitized_nodes = []
    for node in nodes:
        node_id = node["node_id"]
        if node_id not in affected_node_ids:
            kept_nodes.append(node)
            continue
        incident = durable_incident_edges.get(node_id, [])
        if not incident:
            _defer(
                result, proposals, kind="node", item=node,
                reason="node_supported_only_by_prepared_scenario_material",
                refs=[ref for ref in _span_refs(node) if ref in section_by_ref],
            )
            dropped_node_ids.add(node_id)
            continue

        original = deepcopy(node)
        retained_evidence: dict[str, dict[str, Any]] = {}
        for edge in incident:
            for ref in edge.get("evidence_refs", []):
                if isinstance(ref, dict):
                    span_ref = ref.get("source_span_ref_id")
                    if span_ref in all_source_refs and span_ref not in section_by_ref:
                        retained_evidence.setdefault(span_ref, deepcopy(ref))
        node["description"] = ""
        node["evidence_refs"] = [retained_evidence[key] for key in sorted(retained_evidence)]
        if "aliases" in node:
            node["aliases"] = []
        if "corpus_ref" in node:
            node["corpus_ref"] = None
        _with_profile_warning(node)
        kept_nodes.append(node)
        item_id = f"deferred:prepared-scenario:sanitized-node:{node_id}"
        if item_id in proposals or any(
            existing.get("item_id") == item_id
            for existing in result.get("deferred_items", [])
            if isinstance(existing, dict)
        ):
            raise SourceSectionRetentionError("prepared-scenario disposition identity collision")
        proposals[item_id] = {
            "item_id": item_id,
            "kind": "node",
            "proposal": original,
            "decision": "identity_retained_description_and_aliases_cleared",
        }
        sanitized_nodes.append({
            "node_id": node_id,
            "removed_source_span_ref_ids": [
                ref for ref in _span_refs(original) if ref in section_by_ref
            ],
            "retained_edge_ids": sorted(edge["edge_id"] for edge in incident),
            "retained_evidence_span_ref_ids": sorted(retained_evidence),
            "description_cleared": True,
            "aliases_cleared": "aliases" in original,
        })

    kept_node_ids = {node["node_id"] for node in kept_nodes}
    kept_edges: list[dict[str, Any]] = []
    deferred_edge_ids: list[str] = []
    for edge in edges:
        edge_id = edge["edge_id"]
        scene_refs = [ref for ref in _span_refs(edge) if ref in section_by_ref]
        missing_endpoint = (
            edge.get("from_node_id") not in kept_node_ids
            or edge.get("to_node_id") not in kept_node_ids
        )
        if scene_refs or missing_endpoint:
            reason = (
                "relationship_supported_by_prepared_scenario_material"
                if scene_refs else "relationship_endpoint_deferred_with_prepared_scenario_node"
            )
            _defer(
                result, proposals, kind="edge", item=edge, reason=reason,
                refs=[ref for ref in _span_refs(edge) if isinstance(ref, str)],
            )
            deferred_edge_ids.append(edge_id)
            continue
        kept_edges.append(edge)

    result["nodes"] = kept_nodes
    result["edges"] = kept_edges
    deferred_node_ids = sorted(dropped_node_ids)
    return result, {
        "profile": PROFILE,
        "sections": sections,
        "deferred_node_ids": deferred_node_ids,
        "deferred_edge_ids": sorted(deferred_edge_ids),
        "sanitized_node_ids": sorted(item["node_id"] for item in sanitized_nodes),
        "sanitized_nodes": sanitized_nodes,
        "deferred_proposals": {key: proposals[key] for key in sorted(proposals)},
    }


def compile_gazetteer_scenario_scope(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    result, diagnostics = compile_gazetteer_role_citations(graph, rows)
    result, scope_diagnostics = retain_durable_gazetteer_scope(result, rows)
    diagnostics["prepared_scenario_scope"] = scope_diagnostics
    for deferred in result.get("deferred_items", []):
        _with_profile_warning(deferred)
    livestock = diagnostics.get("livestock_semantic_hygiene")
    if isinstance(livestock, dict):
        livestock["profile"] = PROFILE
    return result, diagnostics


GAZETTEER_PREPARED_SCENARIO_PROFILE = register_extraction_profile(replace(
    GAZETTEER_ROLE_CITATION_PROFILE,
    profile_version=PROFILE_VERSION,
    source_section_retainer=compile_gazetteer_scenario_scope,
))

"""Retain exact source-backed trade access details on a Gazetteer location."""

from __future__ import annotations

import re
from copy import deepcopy
from dataclasses import replace
from typing import Any

from .category_candidate_graph_extractor import materialize_promote_evidence_ref
from .extraction_profile import register_extraction_profile
from .worldbuilding_gazetteer_governance import (
    GAZETTEER_GOVERNANCE_PROFILE,
    _document_city_title,
    _matching_city_nodes,
    _normalized_label,
    _physical_source_lines,
    compile_gazetteer_governance_relations,
)
from .worldbuilding_gazetteer_scenario_scope import _heading, _ordered_rows
from .worldbuilding_gazetteer_role_citations import _affirmed_role_occurrence


PROFILE_VERSION = "1.10"
PROFILE = f"worldbuilding_gazetteer_v1@{PROFILE_VERSION}"
_TRADE_ACCESS = re.compile(
    r"(?P<prefix>[^.!?]*\b(?:trade hub|trading hub|commercial hub|market center)"
    r"[^.!?]*?\baccess\s+to\s+)"
    r"(?P<routes>[^.!?]+)[.!?]",
    re.IGNORECASE,
)
_NEGATED_OR_QUALIFIED_ACCESS = re.compile(
    r"\b(?:no|not|never|without|lack(?:s|ing)?|unable|cannot|can't|"
    r"limited|restricted|partial|seasonal|intermittent|occasional|"
    r"could|might|may|would|should)\b",
    re.IGNORECASE,
)
_PLACE_OF_REFERENCE = re.compile(
    r"(?i:\b(?:city|town|port|village|settlement|metropolis|capital)\s+of\s+)"
    r"(?P<name>[A-Z][A-Za-z'’.-]*(?:\s+[A-Z][A-Za-z'’.-]*)*)",
)
_PREPOSITIONAL_CITY_REFERENCE = re.compile(
    r"\b(?:in|at|from|near|within|outside)\s+(?:the\s+)?"
    r"(?:(?:city\s+of)\s+)?"
    r"(?P<name>[A-Z][A-Za-z'’.-]*(?:\s+[A-Z][A-Za-z'’.-]*)*)"
)
_NAMED_CITY_SUBJECT = re.compile(
    r"^\s*(?P<subject>[A-Z][A-Za-z'’.-]*"
    r"(?:\s+(?:of|the|de|du|van|von|[A-Z][A-Za-z'’.-]*))*)"
    r"\s+(?i:is|was|has|serves\s+as)\b",
)
_POSSESSIVE_CITY_SUBJECT = re.compile(
    r"^\s*(?P<subject>[A-Z][A-Za-z'’.-]*(?:\s+[A-Z][A-Za-z'’.-]*)*)['’]s\b"
)
_PROPER_SUBJECT_COMMA = re.compile(
    r"^\s*(?P<subject>[A-Z][A-Za-z'’.-]*(?:\s+[A-Z][A-Za-z'’.-]*)*)\s*,"
)
_GENERIC_CITY_SUBJECT = re.compile(
    r"^\s*(?:it(?:['’]s|\s+(?:is|has|serves\s+as))|"
    r"(?:the|this|that)\s+(?:city|place|location)\s+(?:is|has|serves\s+as)|"
    r"(?:this|that)\s+is)\b",
    re.IGNORECASE,
)
_GENERIC_SENTENCE_OPENING = re.compile(
    r"^\s*(?:a|an)\s+(?:key\s+)?"
    r"(?:trade hub|trading hub|commercial hub|market center)\b",
    re.IGNORECASE,
)


def _trade_section_claims(rows: list[dict[str, Any]]) -> tuple[int, list[dict[str, Any]]]:
    lines = _physical_source_lines(rows)
    sections = [
        index
        for index, row in enumerate(lines)
        if (heading := _heading(row["text"])) is not None
        and heading[0] == 3
        and heading[1].rstrip(":").strip().casefold() == "economy and trade"
    ]
    if len(sections) != 1:
        return len(sections), []

    start = sections[0]
    section_level = 3
    claims = []
    for row in lines[start + 1 :]:
        heading = _heading(row["text"])
        if heading is not None and heading[0] <= section_level:
            break
        for match in _TRADE_ACCESS.finditer(row["text"]):
            claims.append({
                **row,
                "sentence": match.group(0).strip(),
                "routes": match.group("routes").strip(),
                "prefix": match.group("prefix"),
            })
    return 1, claims


def _same_city_reference(name: str, city_name: str) -> bool:
    normalized = _normalized_label(name)
    normalized = re.sub(r"^(?:the\s+)?city\s+of\s+", "", normalized)
    return normalized == _normalized_label(city_name)


def _trade_claim_is_affirmative(claim: dict[str, Any]) -> bool:
    prefix = claim.get("prefix")
    return (
        isinstance(prefix, str)
        and not _NEGATED_OR_QUALIFIED_ACCESS.search(prefix)
        and _affirmed_role_occurrence(str(claim.get("sentence") or ""), "access to")
    )


def _trade_claim_matches_city(claim: dict[str, Any], city_name: str) -> bool:
    prefix = claim.get("prefix")
    if not isinstance(prefix, str):
        return False

    references = [
        match.group("name")
        for pattern in (_PLACE_OF_REFERENCE, _PREPOSITIONAL_CITY_REFERENCE)
        for match in pattern.finditer(prefix)
    ]
    if any(not _same_city_reference(name, city_name) for name in references):
        return False

    subject_match = (
        _NAMED_CITY_SUBJECT.match(prefix)
        or _POSSESSIVE_CITY_SUBJECT.match(prefix)
        or _PROPER_SUBJECT_COMMA.match(prefix)
    )
    if subject_match is None:
        if references or _GENERIC_CITY_SUBJECT.match(prefix):
            return True
        # An unrecognized proper-name opening may still be the sentence subject
        # (for example, "Otherport — a trading hub ..."). Accept only supported
        # article-led hub descriptions; defer other unmatched subjects.
        return _GENERIC_SENTENCE_OPENING.match(prefix) is not None
    subject = subject_match.group("subject")
    if _normalized_label(subject) in {"it", "this", "that", "the city", "the place", "the location"}:
        return True
    return _same_city_reference(subject, city_name)


def _source_binding(node: dict[str, Any]) -> tuple[str, str] | None:
    refs = node.get("evidence_refs")
    if not isinstance(refs, list):
        return None
    bindings = {
        (ref.get("source_artifact_id"), ref.get("source_ref_id"))
        for ref in refs
        if isinstance(ref, dict)
        and ref.get("evidence_role") == "source_evidence"
        and ref.get("can_open_source") is True
        and isinstance(ref.get("source_artifact_id"), str)
        and ref.get("source_artifact_id")
        and isinstance(ref.get("source_ref_id"), str)
        and ref.get("source_ref_id")
    }
    if len(bindings) != 1:
        return None
    artifact_id, source_ref_id = next(iter(bindings))
    return (artifact_id, source_ref_id) if artifact_id and source_ref_id else None


def _attach_trade_evidence(
    node: dict[str, Any], *, source_span_ref_id: str, sentence: str,
    source_artifact_id: str, source_ref_id: str,
) -> str | None:
    refs = node.get("evidence_refs")
    if not isinstance(refs, list):
        return None
    existing = [
        ref for ref in refs
        if isinstance(ref, dict) and ref.get("source_span_ref_id") == source_span_ref_id
    ]
    if len(existing) > 1:
        return None
    if existing:
        ref = existing[0]
        if (
            ref.get("source_artifact_id") != source_artifact_id
            or ref.get("source_ref_id") != source_ref_id
            or ref.get("source_anchor_id") != f"anchor:{source_span_ref_id}"
            or ref.get("evidence_role") != "source_evidence"
            or ref.get("can_open_source") is not True
        ):
            return None
        quotes = ref.get("anchor_quotes")
        if not isinstance(quotes, list):
            return None
        if sentence in quotes:
            return "already_present"
        quotes.append(sentence)
        return "quote_added"

    evidence = materialize_promote_evidence_ref(
        {
            "source_span_ref_id": source_span_ref_id,
            "anchor_quotes": [sentence],
        },
        source_artifact_id=source_artifact_id,
        source_ref_id=source_ref_id,
    )
    if evidence is None or evidence.get("can_open_source") is not True:
        return None
    refs.append(evidence)
    return "attached"


def _apply_trade_context(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    result = deepcopy(graph)
    nodes = result.get("nodes")
    if not isinstance(nodes, list) or any(not isinstance(node, dict) for node in nodes):
        raise ValueError("candidate graph nodes must be a list of objects")

    section_count, claims = _trade_section_claims(_ordered_rows(rows))
    if section_count != 1:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "trade_section_not_unique",
            "section_count": section_count,
        }
    if len(claims) != 1:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "trade_access_claim_not_unique",
            "claim_count": len(claims),
        }
    if not _trade_claim_is_affirmative(claims[0]):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "trade_access_claim_not_affirmative",
            "source_span_ref_id": claims[0].get("source_span_ref_id"),
        }

    title = _document_city_title(rows)
    if title is None:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "city_title_unresolved",
        }
    city_name, _title_row = title
    if not _trade_claim_matches_city(claims[0], city_name):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "trade_city_subject_mismatch",
            "source_span_ref_id": claims[0].get("source_span_ref_id"),
        }
    locations = _matching_city_nodes(nodes, city_name)
    if len(locations) != 1:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "city_location_not_unique",
            "location_count": len(locations),
        }

    location = locations[0]
    claim = claims[0]
    source_span_ref_id = str(claim.get("source_span_ref_id") or "")
    binding = _source_binding(location)
    if (
        binding is None
        or not source_span_ref_id.startswith(binding[0] + ":span:")
    ):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "trade_source_binding_unverified",
            "source_span_ref_id": source_span_ref_id,
        }

    if not isinstance(location.get("description"), (str, type(None))):
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "city_description_invalid",
            "source_span_ref_id": source_span_ref_id,
        }

    evidence_status = _attach_trade_evidence(
        location,
        source_span_ref_id=source_span_ref_id,
        sentence=claim["sentence"],
        source_artifact_id=binding[0],
        source_ref_id=binding[1],
    )
    if evidence_status is None:
        return result, {
            "profile": PROFILE,
            "status": "skipped",
            "reason": "trade_evidence_conflict",
            "source_span_ref_id": source_span_ref_id,
        }

    description = str(location.get("description") or "")
    route_text = _normalized_label(claim["routes"])
    description_text = _normalized_label(description)
    description_status = "already_present"
    if route_text not in description_text:
        support_line = f"Trade access: {claim['routes']}."
        location["description"] = f"{description.rstrip()}\n\n{support_line}".strip()
        description_status = "added"

    status = (
        "added"
        if description_status == "added" or evidence_status != "already_present"
        else "already_present"
    )
    return result, {
        "profile": PROFILE,
        "status": status,
        "description_status": description_status,
        "evidence_status": evidence_status,
        "node_id": location.get("node_id"),
        "source_span_ref_id": source_span_ref_id,
        "source_quote": claim["sentence"],
    }


def compile_gazetteer_trade_context(
    graph: dict[str, Any], rows: list[dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    result, diagnostics = compile_gazetteer_governance_relations(graph, rows)
    result, trade_diagnostics = _apply_trade_context(result, rows)
    diagnostics["source_grounded_trade_context"] = trade_diagnostics
    return result, diagnostics


GAZETTEER_TRADE_CONTEXT_PROFILE = register_extraction_profile(replace(
